MOTOR_PARAM_INERTIA = SM060R20B30MNAD_INERTIA;

MOTOR_PARAM_FRICTION = SM060R20B30MNAD_FRICTION;

% Absolute mechanical speed-command limit in rpm. It is divided by MOTOR_PARAM_MAX_SPEED to obtain the controller PU limit.
MCS_MECH_SPEED_LIMIT_RPM = real2param(3000.0);

% Maximum mechanical speed-command slew rate in rpm/s. The configured value corresponds to 1 PU/s for the selected 3000 rpm motor.
MCS_MECH_SPEED_SLOPE_RPM_S = real2param(3000.0);

% Absolute q-axis current/torque command limit in amperes. It is divided by CTRL_CURRENT_BASE to obtain the controller PU limit; 3 A corresponds to the previous 0.3 PU setting.
MCS_MECH_CURRENT_LIMIT_A = real2param(3.0);

% Rectangular saturation limit for d/q axes in V.
MCS_MAX_RECT_SATURATION_VOLTAGE_V = real2param(10.0);

MCS_MAX_DC_BUS_VOLTAGE_V = CTRL_DCBUS_VOLTAGE*1.2;

% Controller startup delay in milliseconds.
CTRL_STARTUP_DELAY = 100;

% Minimum delay in milliseconds before the CiA402 state machine enters Operation Enabled. The project control tick is expressed in milliseconds.
MCS_CIA402_OPERATION_ENABLE_DELAY_MS = 100;

% Cutoff frequency in hertz of the low-pass filter applied to encoder-derived mechanical speed.
MCS_ENCODER_SPEED_FILTER_FC_HZ = real2param(20.0);

% Enable sensored phase-A alignment, pole-pair detection and encoder-offset calibration before electrical/mechanical identification.
MCS_PMSM_ID_ENABLE_ENCODER_CALIBRATION = 1;

% Closed-loop d-axis current in amperes used to lock the rotor to phase A during encoder calibration.
MCS_PMSM_ID_ENCODER_ALIGN_CURRENT_A = real2param(1.0);

% PWM-off observation time in seconds used to detect a randomly jumping encoder.
MCS_PMSM_ID_ENCODER_NOISE_CHECK_TIME_S = real2param(0.10);

% Time in seconds allowed for the rotor to settle at the phase-A electrical zero.
MCS_PMSM_ID_ENCODER_ALIGN_SETTLE_TIME_S = real2param(0.30);

% Electrical revolutions per second used while rotating the alignment current vector.
MCS_PMSM_ID_ENCODER_SWEEP_ELEC_HZ = real2param(1.0);

% Dwell time in seconds at phase A after each complete electrical revolution.
MCS_PMSM_ID_ENCODER_ANCHOR_SETTLE_TIME_S = real2param(0.10);

% Maximum wrapped mechanical-position change accepted in one control ISR sample.
MCS_PMSM_ID_ENCODER_MAX_SAMPLE_JUMP_PU = real2param(0.02);

% Maximum unwrapped position span accepted during the PWM-off encoder noise test.
MCS_PMSM_ID_ENCODER_MAX_STATIONARY_SPAN_PU = real2param(0.002);

% Minimum net mechanical motion required during one electrical revolution; below this reports an uncoupled/stuck encoder.
MCS_PMSM_ID_ENCODER_MIN_CYCLE_MOTION_PU = real2param(0.02);

% Maximum absolute deviation of each electrical-cycle mechanical motion from the measured mean.
MCS_PMSM_ID_ENCODER_MAX_CYCLE_DEVIATION_PU = real2param(0.03);

% Maximum wrapped mechanical-position error accepted when returning to the first phase-A anchor.
MCS_PMSM_ID_ENCODER_ZERO_RETURN_TOLERANCE_PU = real2param(0.02);

% Maximum pole-pair count searched before encoder calibration stops with a zero-return fault.
MCS_PMSM_ID_ENCODER_MAX_POLE_PAIRS = 16;

% Cutoff frequency in hertz of the second-order low-pass filter used while estimating ADC zero offsets.
MCS_ADC_CALIBRATOR_FC_HZ = real2param(20.0);

% Quality factor of the ADC calibration low-pass filter; 0.707 gives an approximately Butterworth second-order response.
MCS_ADC_CALIBRATOR_Q = real2param(0.707);

% D-axis current reference in amperes used by BUILD_LEVEL 2 and 3 commissioning. Converted to PU using CTRL_CURRENT_BASE.
MCS_COMMISSIONING_ID_REF_A = real2param(1.0);

% Q-axis current reference in amperes used by BUILD_LEVEL 2 and 3 commissioning. Converted to PU using CTRL_CURRENT_BASE.
MCS_COMMISSIONING_IQ_REF_A = real2param(1.0);

% Mechanical speed reference in rpm used by BUILD_LEVEL 4 commissioning. Converted to PU using MOTOR_PARAM_MAX_SPEED.
MCS_COMMISSIONING_SPEED_REF_RPM = real2param(300.0);

% Position-loop proportional gain. Input is mechanical position error in PU revolutions and output is speed reference in PU, so the gain is speed_pu/position_pu.
MCS_MECH_POSITION_KP_PU = real2param(5.0);

% Position-loop integral gain in speed_pu/(position_pu*s). The continuous gain is divided by the mechanical-loop sampling frequency internally.
MCS_MECH_POSITION_KI_PU_S = real2param(1.0);

% Velocity-loop proportional gain. Input is speed error in PU and output is q-axis current/torque reference in PU, so the gain is current_pu/speed_pu.
MCS_MECH_VELOCITY_KP_PU = real2param(5.0);

% Velocity-loop integral gain in current_pu/(speed_pu*s). The continuous gain is divided by the mechanical-loop sampling frequency internally.
MCS_MECH_VELOCITY_KI_PU_S = real2param(1.0);

% Enable the target ADC-calibration preparation handshake.
MCS_PMSM_ID_ENABLE_PREPARE = 1;

% Enable stator-resistance and inverter dead-time voltage identification.
MCS_PMSM_ID_ENABLE_RS_DT = 1;

