MCS_PMSM_ID_LDQ_MAX_BIAS_CURRENT_A = real2param(5.0);

% Number of bias points recorded for each inductance axis.
MCS_PMSM_ID_LDQ_BIAS_STEPS = 12;

% D-axis alignment current in amperes used before inductance pulses.
MCS_PMSM_ID_LDQ_ALIGN_CURRENT_A = real2param(5.0);

% Bias-current settling time in seconds before each inductance pulse.
MCS_PMSM_ID_LDQ_SETTLE_TIME_S = real2param(0.2);

% Inductance voltage-pulse duration in seconds.
MCS_PMSM_ID_LDQ_PULSE_TIME_S = real2param(0.002);

% Zero-voltage cooldown time in seconds between inductance pulses.
MCS_PMSM_ID_LDQ_COOLDOWN_TIME_S = real2param(0.05);

% Enable PM flux-linkage identification.
MCS_PMSM_ID_ENABLE_FLUX = 1;

% Minimum mechanical speed in rpm used by the flux-linkage regression.
MCS_PMSM_ID_FLUX_MIN_SPEED_RPM = real2param(300.0);

% Maximum mechanical speed in rpm used by the flux-linkage regression.
MCS_PMSM_ID_FLUX_MAX_SPEED_RPM = real2param(1800.0);

% Number of speed points used by the flux-linkage regression.
MCS_PMSM_ID_FLUX_STEPS = 6;

% Current magnitude in amperes used for I/F flux-linkage rotation.
MCS_PMSM_ID_FLUX_IF_CURRENT_A = real2param(4.0);

% Settling time in seconds at each flux-identification speed.
MCS_PMSM_ID_FLUX_SETTLE_TIME_S = real2param(2.0);

% Number of ISR samples averaged at each flux-identification speed.
MCS_PMSM_ID_FLUX_MEASURE_POINTS = 2000;

% Enable the sensored constant-Iq acceleration and PWM-off coast-down mechanical identification stage.
MCS_PMSM_ID_ENABLE_MECHANICAL_ID = 1;

% User-selected mechanical target speed in rpm for the identification test.
MCS_PMSM_ID_MECH_TARGET_SPEED_RPM = real2param(1000.0);

% User-selected q-axis current in amperes applied by the real current loop during acceleration.
MCS_PMSM_ID_MECH_ACCEL_CURRENT_A = real2param(1.0);

% Lower acceleration/coast fitting boundary relative to the selected target speed.
MCS_PMSM_ID_MECH_FIT_LOW_RATIO = real2param(0.30);

% Upper acceleration/coast fitting boundary relative to the selected target speed.
MCS_PMSM_ID_MECH_FIT_HIGH_RATIO = real2param(0.70);

% Target-speed ratio at which PWM is physically disabled to start free coast-down.
MCS_PMSM_ID_MECH_PWM_OFF_RATIO = real2param(0.75);

% Safety timeout in seconds covering acceleration and free coast-down.
MCS_PMSM_ID_MECH_MAX_TEST_TIME_S = real2param(20.0);

% Expected maximum combined duration of the two recorded 30%-70% speed curves.
MCS_PMSM_ID_MECH_RECORD_TIME_S = real2param(10.0);

% Minimum coefficient of determination accepted for acceleration-versus-speed regression.
MCS_PMSM_ID_MECH_MIN_FIT_R2 = real2param(0.80);

